-- See LOGIN_TROUBLESHOOTING.md. cardN numbers can swap between boots and by-path names
-- contain ':' (the list delimiter), so resolve the fixed PCI addresses to cardN at load.
-- Intel first (primary), then NVIDIA. If nothing resolves, Aquamarine auto-detects.
do
    local cards = {}
    for _, pci in ipairs({ "0000:00:02.0", "0000:01:00.0" }) do
        local p = io.popen("timeout 1 readlink -e /dev/dri/by-path/pci-" .. pci .. "-card 2>/dev/null")
        local card = p and p:read("l")
        if p then p:close() end
        if card and card ~= "" then
            cards[#cards + 1] = card
        end
    end
    if #cards > 0 then
        hl.env("AQ_DRM_DEVICES", table.concat(cards, ":"))
    end
end

