-- Colours generated by wallust ($colorN = rgb(...)).
local colors = {}
do
    local f = io.open(hypr .. "/wallust/wallust-hyprland.conf", "r")
    if f then
        for line in f:lines() do
            local name, value = line:match("^%s*%$(%w+)%s*=%s*(%S+)")
            if name then
                colors[name] = value
            end
        end
        f:close()
    end
end

