-- Animations: parsed from UserAnimations.conf so the animations menu keeps working.
do
    local f = io.open(hypr .. "/UserConfigs/UserAnimations.conf", "r")
    if f then
        for raw in f:lines() do
            local line = raw:gsub("#.*$", "")
            local key, value = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
            local parts = {}
            for part in (value or ""):gmatch("[^,]+") do
                parts[#parts + 1] = part:match("^%s*(.-)%s*$")
            end
            if key == "enabled" then
                local on = value == "yes" or value == "true" or value == "on" or value == "1"
                hl.config({ animations = { enabled = on } })
            elseif key == "bezier" and #parts == 5 then
                hl.curve(parts[1], {
                    type   = "bezier",
                    points = {
                        { tonumber(parts[2]), tonumber(parts[3]) },
                        { tonumber(parts[4]), tonumber(parts[5]) },
                    },
                })
            elseif key == "animation" and #parts >= 2 then
                local anim = { leaf = parts[1], enabled = parts[2] == "1" }
                -- Lua API caps speed at 100 (old presets use e.g. borderangle 180).
                if parts[3] then anim.speed = math.min(tonumber(parts[3]), 100) end
                if parts[4] then anim.bezier = parts[4] end
                if parts[5] then anim.style = parts[5] end
                hl.animation(anim)
            end
        end
        f:close()
    end
end

