local function run(cmd)
    return hl.dsp.exec_cmd(cmd)
end

local function bind(keys, description, action, opts)
    opts = opts or {}
    opts.description = description
    return hl.bind(keys, action, opts)
end

local function zoom(factor)
    return function()
        local current = hl.get_config("cursor.zoom_factor") or 1
        hl.config({ cursor = { zoom_factor = math.max(current * factor, 1) } })
    end
end

-- Replacement for the removed `workspaceopt allfloat`.
local function toggle_float_all()
    local windows = hl.get_workspace_windows(hl.get_active_workspace())
    local action = "disable"
    for _, w in ipairs(windows) do
        if not w.floating then
            action = "enable"
            break
        end
    end
    for _, w in ipairs(windows) do
        hl.dispatch(hl.dsp.window.float({ window = w, action = action }))
    end
end

