-- Resize, move, swap, focus (arrow keys)
for key, dir in pairs({ left = "left", right = "right", up = "up", down = "down" }) do
    local delta = ({ left = { -50, 0 }, right = { 50, 0 }, up = { 0, -50 }, down = { 0, 50 } })[key]
    bind(mod .. " + SHIFT + " .. key, "resize " .. dir, hl.dsp.window.resize({ x = delta[1], y = delta[2], relative = true }), { repeating = true })
    bind(mod .. " + CTRL + " .. key, "move window " .. dir, hl.dsp.window.move({ direction = dir }))
    bind(mod .. " + ALT + " .. key, "swap window " .. dir, hl.dsp.window.swap({ direction = dir }))
    bind(mod .. " + " .. key, "focus " .. dir, hl.dsp.focus({ direction = dir }))
end

