    wallpaper = "^([Ww]aytrogen)$",
    settings = "^(nwg-displays|nwg-look|qt[56]ct|pavucontrol|org.pulseaudio.pavucontrol|com.saivert.pwvucontrol|wihotspot|btrfs-assistant|timeshift-gtk|gnome-disks|file-roller|org.gnome.FileRoller|nm-applet|nm-connection-editor|blueman-manager|org.kde.polkit-kde-authentication-agent-1|[Rr]ofi|seahorse)$",
    viewer = "^(gnome-system-monitor|org.gnome.SystemMonitor|evince|eog|org.gnome.Loupe)$",
    notif = "^(swaync-.*)$",
    scrcpy = "^(scrcpy)$",
}
for tag, class in pairs(classTags) do
    rule({ class = class }, { tag = "+" .. tag })
end
rule({ class = "^([Gg]oogle-chrome(-beta|-dev|-unstable)?|chrome-.+-Default|[Cc]hromium|[Mm]icrosoft-edge(-stable|-beta|-dev|-unstable)?|Brave-browser(-beta|-dev|-unstable)?|zen-alpha|zen|[Tt]horium-browser|[Cc]achy-browser)$" }, { tag = "+browser" })
rule({ class = "^([Ss]team)$" }, { tag = "+gamestore" })
rule({ title = "^([Ll]utris)$" }, { tag = "+gamestore" })
rule({ class = "^(com.heroicgameslauncher.hgl)$" }, { tag = "+gamestore" })
rule({ title = "^(KooL Quick Cheat Sheet)$" }, { tag = "+KooL_Cheat" })
rule({ title = "^(KooL Hyprland Settings)$" }, { tag = "+KooL_Settings" })
rule({ title = "^(atur\\.sh)$" }, { tag = "+custom_script" })
rule({ title = "^(ceklog\\.sh)$" }, { tag = "+custom_script" })

-- Workspaces
rule({ tag = "im" }, { workspace = "2" })
rule({ tag = "projects" }, { workspace = "3" })
rule({ tag = "gamestore" }, { workspace = "5" })
rule({ tag = "multimedia" }, { workspace = "9 silent" })
rule({ tag = "browser" }, { workspace = "2" })
rule({ class = "^(Brave-browser)$" }, { workspace = "1" })
rule({ class = "^([Ff]irefox)$" }, { workspace = "1" })
rule({ class = "^([Ww]asitlos)$" }, { workspace = "1" })

-- Opacity
rule({ tag = "browser" }, { opacity = "0.99 0.8" })
rule({ tag = "projects" }, { opacity = "0.9 0.8" })
rule({ tag = "im" }, { opacity = "0.94 0.86" })
rule({ tag = "multimedia" }, { opacity = "0.94 0.86" })
rule({ tag = "file-manager" }, { opacity = "0.9 0.8" })
rule({ tag = "terminal" }, { opacity = "0.9 0.7" })
rule({ tag = "settings" }, { opacity = "0.8 0.7" })
rule({ tag = "viewer" }, { opacity = "0.82 0.75" })
rule({ tag = "wallpaper" }, { opacity = "0.9 0.7" })
rule({ tag = "multimedia_video" }, { no_blur = true, opacity = "1.0" })
rule({ tag = "games" }, { no_blur = true, immediate = true })

-- Behaviour
rule({ fullscreen = true }, { idle_inhibit = "fullscreen" })
rule({ class = ".*" }, { suppress_event = "maximize" })

-- Floating
rule({ tag = "KooL_Cheat" }, { float = true, center = true, size = "monitor_w*0.65 monitor_h*0.9" })
rule({ tag = "KooL_Settings" }, { float = true, center = true })
rule({ tag = "settings" }, { float = true, center = true, size = "monitor_w*0.7 monitor_h*0.7" })
rule({ tag = "viewer" }, { float = true, center = true })
rule({ tag = "wallpaper" }, { float = true, center = true, size = "monitor_w*0.7 monitor_h*0.7" })
rule({ class = "^([Ff]erdium)$" }, { float = true, center = true, size = "monitor_w*0.6 monitor_h*0.7" })
rule({ title = "^(Authentication Required|Save As|Add Folder to Workspace)$" }, { float = true, center = true, size = "monitor_w*0.7 monitor_h*0.6" })
rule({ class = "^(yad)$" }, { float = true, center = true, size = "monitor_w*0.2 monitor_h*0.2" })
rule({ class = "^(mpv|com.github.rafostar.Clapper)$" }, { float = true })
rule({ tag = "scrcpy" }, { float = true, move = "monitor_w*0.78 monitor_h*0.05" })
rule({ tag = "custom_script" }, { float = true, center = true, size = "767 675", opacity = "0.9 0.8" })

hl.window_rule({
    name              = "Picture-in-Picture",
    match             = { title = "^(Picture-in-Picture)$" },
    float             = true,
    pin               = true,
    move              = "monitor_w*0.72 monitor_h*0.07",
    opacity           = "0.95 0.75",
    keep_aspect_ratio = true,
    size              = "monitor_w*0.3 monitor_h*0.3",
})

hl.window_rule({
    name   = "Thunar-Progress-bar",
    match  = { class = "^(thunar)$", title = "^(File Operation Progress)$" },
    float  = true,
    center = true,
    size   = "monitor_w*0.26 monitor_h*0.18",
})

-- Layer rules
hl.layer_rule({ match = { namespace = "rofi" }, blur = true })
hl.layer_rule({ match = { namespace = "notifications" }, blur = true })
hl.layer_rule({ match = { namespace = "quickshell:overview" }, blur = true, ignore_alpha = 0.5 })
hl.layer_rule({ match = { namespace = "waybar" }, blur = true, ignore_alpha = 0.2 })
-- SwayNC (toasts + notification center): frosted glass, slide down from the top, centered
for _, ns in ipairs({ "swaync-control-center", "swaync-notification-window" }) do
    hl.layer_rule({ match = { namespace = ns }, blur = true, ignore_alpha = 0.3, xray = false, animation = "slide top" })
end

-- Blur mode, last so its opacity override wins. Written by scripts/ChangeBlur.sh.
load_if_exists(hypr .. "/UserConfigs/BlurMode.lua")
